        body: 'پاسخ قطعی و علمی «بله» است. دندان‌های شیری نیز همانند دندان‌های دائمی ساختاری شامل مینا، عاج، مغز دندان (پالپ یا همان عصب و عروق) و ریشه‌های محکم دارند. ضخامت مینا و عاج در دندان‌های شیری تقریباً نصف دندان‌های دائمی است؛ به همین دلیل است که یک پوسیدگی کوچک سطحی، به‌خصوص در مواجهه با خطراتی مانند [سندرم شیشه شیر یا پوسیدگی زودرس نوزاد](/articles/baby-bottle-tooth-decay-and-infant-oral-hygiene#what-is-early-childhood-caries-ecc)، با سرعتی باورنکردنی طی چند ماه به عصب دندان نفوذ کرده و سبب دندان‌درد، آبسه و تورم چرکی می‌شود. هنگامی که زمان افتادن فیزیولوژیک دندان شیری فرامی‌رسد، ریشه آن با فشار جوانه دندان دائمی زیرین به آرامی تحلیل رفته و آب می‌شود؛ به همین علت وقتی دندان شیری می‌افتد، والدین فکر می‌کنند این دندان از اول ریشه نداشته است!',
