        body: 'یکی از حیاتی‌ترین نکات در بهداشت دهان کودکان، شناخت «دندان آسیاب اول دائمی» یا همان «دندان ۶ سالگی» است. این دندان در سن ۶ الی ۷ سالگی دقیقاً در انتهای قوس فک و پشت آخرین دندان شیری رویش می‌یابد؛ به این معنی که برای رویش آن، هیچ دندان شیری نمی‌افتد و لقی رخ نمی‌دهد! به همین دلیل، متاسفانه بیش از ۸۰ درصد والدین تصور می‌کنند این دندان نیز شیری است و با بروز پوسیدگی، درمان آن را پشت گوش می‌اندازند. دندان ۶ ستون اصلی و شاه‌کلید جفت‌شدن دندان‌ها و شکل فک است و با رویش آن، باید شیارپوش (فیشورسیلانت) و مراقبت ویژه بهداشتی آغاز گردد.',
