        body: 'پدیده متولد شدن نوزاد با دندان در دهان (دندان ناتال یا Natal Teeth) یا رویش دندان در ۳۰ روز نخست زندگی (دندان نئوناتال) اتفاقی نادر (تقریباً ۱ در هر ۲۰۰۰ تا ۳۰۰۰ تولد) اما کاملاً شناخته‌شده در دندانپزشکی است. این دندان‌ها غالباً همان دندان‌های شیری پیشین فک پایین هستند که به دلیل تکامل زودهنگام جوانه بیرون آمده‌اند، اما ریشه‌ای ضعیف و ناکامل دارند. خطرات اصلی دندان ناتال شامل: زخم شدن زیر زبان نوزاد حین مکیدن شیر (زخم ریگا-فده)، ایجاد زخم و شقاق دردناک در سینه مادر، و خطر بسیار مهم‌تر «لق شدن و کنده شدن دندان و ورود آن به مجاری تنفسی نوزاد» است. در صورت لقی قابل توجه، دندانپزشک با مداخله‌ای سریع و بدون درد، دندان را خارج می‌سازد.',
