        title: 'عوارض مکیدن مداوم انگشت و پستانک بر رشد فک و دندان‌ها',
        body: 'مکیدن یک واکنش طبیعی، آرام‌بخش و غریزی در نوزادان است که احساس امنیت به آن‌ها می‌بخشد. با این حال، اگر این عادت پس از رویش دندان‌های شیری و در سنین نوپایی همچنان با شدت ادامه یابد، نیروهای مکانیکی نامتناسبی به استخوان‌های در حال رشد فک وارد می‌سازد.\n\nشایع‌ترین آسیب‌های ناشی از مکیدن طولانی‌مدت انگشت و پستانک:\n- **اپن‌بایت قدامی (Open Bite):** ایجاد فاصله عمودی میان دندان‌های جلویی بالا و پایین به‌طوری که هنگام بستن دهان، دندان‌های پیشین به هم نمی‌رسند.\n- **جلوزدگی دندان‌های بالا (Overjet شدید):** هل داده شدن دندان‌های پیشین فک بالا به سمت بیرون که احتمال ضربه و شکستگی آن‌ها را افزایش می‌دهد.\n- **تنگی قوس فک بالا و کراس‌بایت خلفی:** ایجاد سقف دهان گنبدی و باریک به دلیل فشار منفی گونه‌ها حین مکیدن مداوم.\n- **اختلالات گفتاری و تلفظی:** نوک‌زبانی صحبت کردن کودک و ناتوانی در تلفظ صحیح حروفی مانند «س» و «ز».',
        doctorComment: 'مکیدن انگشت شست معمولاً آسیب بیشتری نسبت به پستانک به فک وارد می‌کند؛ زیرا انگشت جسمی سفت و اهرمی است و ترک آن برای کودک دشوارتر است. هرچه این عادت‌ها قبل از ۳ سالگی زودتر کنار گذاشته شوند، استخوان فک فرصت بیشتری برای بازگشت خودبه‌خودی به فرم نرمال خواهد داشت.'
