        body: 'ارتودنسی پیشگیرانه (Preventive & Interceptive Orthodontics) مجموعه‌ای از اقدامات درمانی بهنگام است که هدف آن هدایت رشد استخوان‌های فک، حفظ فضای دندان‌های دائمی پس از کشیده شدن زودهنگام دندان شیری (از طریق [دستگاه‌های فضانگهدار دندان](/articles/primary-baby-teeth-guide#consequences-of-early-tooth-loss)) و جلوگیری از تبدیل ناهنجاری‌های ساده به جراحی‌های پیچیده فکی در بزرگسالی است. انجمن ارتودنتیست‌های آمریکا (AAO) تاکید می‌کند که تمام کودکان باید حداکثر در **سن ۷ سالگی** تحت معاینه تخصصی ارتودنسی قرار گیرند.\n\nچرا سن ۷ سالگی اهمیت حیاتی دارد؟\n- رویش [دندان آسیاب اول دائمی یا دندان ۶ سالگی](/articles/tooth-eruption-timeline-and-stages#first-permanent-molar-six-year-tooth) و دندان‌های پیشین دائمی در این سن، وضعیت جفت شدن فک‌ها را مشخص می‌کند.\n- استخوان فک در این سن هنوز نرم و منعطف بوده و پاسخ فوق‌العاده‌ای به پلاک‌های ارتوپدی متحرک فکی می‌دهد.\n- اصلاح عقب‌ماندگی فک بالا یا انحرافات فکی در این سن، از نیاز به جراحی ارتوگناتیک (جراحی ترکیبی فک) در سن ۱۸ سالگی پیشگیری می‌نماید.',
