        body: 'یکی از شایع‌ترین باورهای غلط که متاسفانه گاهی باعث قطع خودسرانه مکمل آهن توسط والدین و ابتلای کودک به کم‌خونی فقر آهن و اختلالات رشد مغزی می‌شود، این باور است که «قطره آهن دندان‌های کودک را می‌پوساند و از بین می‌برد». تحقیقات قاطع دندانپزشکی نشان داده‌اند که املاح آهن به هیچ عنوان ساختار مینای دندان را تضعیف یا پوسیده نمی‌کنند.\n\nحقایق علمی درباره رنگ‌پذیری دندان با آهن:\n- **تغییر رنگ کاملاً سطحی است:** ترکیبات آهن با سولفید هیدروژن تولیدشده توسط باکتری‌های دهان واکنش داده و رسوب سطحی سیاه یا قهوه‌ای ایجاد می‌کنند که هیچ ارتباطی با پوسیدگی عمقی ندارد.\n- **پوسیدگی‌های پنهان مقصر اصلی هستند:** اگر دندان از قبل به دلیل مواجهه با شیر شبانه دچار [سندرم شیشه شیر یا پوسیدگی زودرس نوزاد](/articles/baby-bottle-tooth-decay-and-infant-oral-hygiene#what-is-early-childhood-caries-ecc) شده باشد، قطره آهن در آن حفره‌های متخلخل نفوذ کرده و آن را سیاه نشان می‌دهد؛ والدین این سیاهی را به اشتباه علت پوسیدگی می‌دانند.\n- **رنگدانه‌ها قابل پاک‌سازی هستند:** این رسوبات سطحی به راحتی با اجرای [پروتکل بهداشت دهان نوزاد و مسواک انگشتی](/articles/baby-bottle-tooth-decay-and-infant-oral-hygiene#infant-oral-hygiene-protocol-step-by-step) و در صورت نیاز با یک بروساژ ساده و بدون درد در کلینیک دندانپزشکی پاک می‌شوند.',
