        body: 'بسیاری از بیماران هنگام مسواک زدن یا نخ دندان کشیدن با دیدن خون‌آبه در سینک دستشویی نگران می‌شوند یا برعکس، تصور می‌کنند این خونریزی امری طبیعی یا ناشی از زبری مسواک است. در یک لثه سالم و مقاوم، عروق خونی زیر یک لایه محافظتی متراکم از بافت کراتینه‌شده قرار دارند و حتی با مسواک زدن دقیق یا کشیدن نخ دندان نیز هرگز دچار خونریزی نمی‌شوند. علت اصلی خونریزی، تجمع لایه‌ای نامرئی، چسبنده و متشکل از میلیون‌ها باکتری به نام **پلاک میکروبی (بیوفیلم دندانی)** در طوق دندان و لبه لثه است.\n\nهنگامی که این پلاک ظرف ۲۴ تا ۴۸ ساعت با مسواک و نخ دندان تمیز نشود، باکتری‌ها سموم التهاب‌زایی ترشح می‌کنند که سیستم ایمنی بدن را تحریک می‌کند. در پاسخ به این هجوم، بدن برای رساندن گلبول‌های سفید، مویرگ‌های خونی بافت لثه را گشاد و پرخون می‌کند. این مویرگ‌های ملتهب دیواره‌ای بسیار نازک، شکننده و آسیب‌پذیر پیدا می‌کنند که با کوچک‌ترین تماس فیزیکی موهای مسواک یا نخ دندان پاره شده و دچار خونریزی می‌شوند.',
        doctorComment: 'بزرگ‌ترین اشتباهی که افراد مرتکب می‌شوند این است که با دیدن اولین قطره خون، مسواک زدن یا نخ دندان کشیدن آن ناحیه را متوقف می‌کنند! این کار دقیقاً چرخه معیوب را تشدید می‌کند؛ زیرا تجمع باکتری در آن ناحیه بیشتر شده و التهاب عمیق‌تر می‌شود. راهکار درست، مسواک زدن ملایم‌تر اما مداوم با موهای نرم و کشیدن دقیق نخ دندان است تا پلاک پاک شود.'
