        body: 'شایع‌ترین باوری که باعث ترس افراد از جرم‌گیری می‌شود این جمله معروف است: «جرم‌گیری لایه محافظ دندان را می‌تراشد و مینا را نازک می‌کند!» برای درک نادرست بودن این ادعا، شناخت فیزیک قلم جرم‌گیری و بافت دندان ضروری است:\n\nمینای دندان سخت‌ترین ماده آلی در تمام بدن انسان است؛ سختی مینا از استخوان بسیار فراتر بوده و ساختاری فوق‌العاده متراکم از کریستال‌های هیدروکسی‌آپاتیت دارد. در دندانپزشکی مدرن، دستگاه‌های جرم‌گیری (اولتراسونیک یا پیزوالکتریک) هیچ‌گونه تیغ، فرز برنده یا سطح ساینده‌ای ندارند. این قلم‌ها تنها با **امواج لرزشی بسیار سریع با فرکانس بالا (۲۵ تا ۴۰ هزار بار در ثانیه)** کار می‌کنند.\n\nنوک ظریف قلم جرم‌گیری به همراه اسپری پرفشار آب خنک، بدون آنکه بتواند ذره‌ای از بافت سخت مینا را بردارد، پیوند شکننده و گچی جرم‌های کلسیمه‌شده (تارتار) را در هم می‌شکند و آن‌ها را از سطح دندان جدا می‌سازد. صدای سایش یا لرزشی که بیمار حس می‌کند، صرفاً برخورد این امواج صوتی با سنگ‌ریزه‌های جرم است، نه تراشیده شدن مینا.',
        doctorComment: 'بسیاری از بیماران می‌پرسند چرا بعد از جرم‌گیری سطح دندان زبر به نظر می‌رسد؟ پس از جدا شدن سنگ‌های ضخیم جرم، سطح میکروسکوپی مینا که ماه‌ها زیر رسوبات خفه شده بود احساس می‌شود. ما در انتهای هر جلسه با مرحله «بروساژ» و خمیرهای صیقل‌دهنده مخصوص، تمام سطوح دندان را کاملاً صیقلی، براق و نفوذناپذیر می‌کنیم.'
