        body: 'در سال‌های اخیر تبلیغات فراوانی پیرامون «پودر زغال فعال یا خمیردندان‌های سیاه زغالی» به عنوان معجزه سفیدکننده ارگانیک در شبکه‌های اجتماعی دیده می‌شود. مرور مقالات منتشرشده توسط انجمن دندانپزشکی آمریکا (JADA) صراحتاً اعلام کرده است که هیچ شواهد علمی مبنی بر اثربخشی یا ایمنی درازمدت محصولات زغالی وجود ندارد.\n\nواقعیت علمی زغال بر روی دندان چیست؟\n- **سایش فیزیکی شدید (Abrasivity):** ذرات کربن فعال ذراتی بسیار تیز، متراکم و ساینده هستند. وقتی زغال را روی دندان‌ها مسواک می‌زنید، عملکردی مانند یک کاغذ سنباده زبر روی رنگ یک خودروی لوکس دارد!\n- **زردتر شدن دندان‌ها در بلندمدت:** لایه سطحی مینای دندان نیمه‌شفاف و سفید است، در حالی که لایه زیرین آن (عاج) ذاتاً زردرنگ است. زغال با تراشیدن و نازک کردن مینا، در روزهای اول شاید لکه‌های سطحی چای را با خراشیدن بردارد، اما پس از مدتی عاج زرد از زیر مینای نازک‌شده بیرون می‌زند و دندان برای همیشه زردرنگ، کدر و به شدت حساس می‌شود.\n- **عدم جذب فلوراید:** ذرات کربن فعال فلوراید موجود در خمیردندان را جذب و بی‌اثر می‌کنند و مانع از [محافظت ضد اسید فلوراید در مینا](/articles/mouthwash-and-fluoride-therapy-guide#fluoride-remineralization-mechanism) می‌شوند.'
