        body: 'شاید بارها شنیده باشید که فلوراید برای دندان خوب است، اما بیایید ببینیم پشت صحنه چه اتفاقی می‌افتد:\n\nهر بار که شیرینی، نان، برنج یا میوه می‌خورید، میکروب‌های دهان از قند آن‌ها تغذیه کرده و اسید تولید می‌کنند. این اسید درست مثل قطره‌های باران اسیدی، املاح کلسیم سطح دندان را در خود حل می‌کند و دندان را نرم و مستعد سوراخ شدن می‌سازد.\n\nفلوراید اینجا مثل یک تیم مرمت حرفه‌ای وارد میدان می‌شود:\n- **ساخت یک پوشش فوق‌العاده سخت:** وقتی فلوراید به مینای دندان می‌رسد، با املاح دندان ترکیب می‌شود و ساختاری جدید می‌سازد که دیگر اسید باکتری‌ها زورشان به آن نمی‌رسد! یعنی دندان شما در برابر پوسیدگی به شدت سرسخت و نفوذناپذیر می‌شود.\n- **ترمیم لکه‌های اولیه خرابی:** اگر دندانی تازه شروع به پوسیدگی کرده باشد (همان لکه‌های سفید گچی کمرنگ)، فلوراید با برگرداندن کلسیم و فسفات به بافت دندان، آن را دوباره سفت می‌کند و جلوی سوراخ شدن و نیاز به پر کردن را می‌گیرد.\n- **دستپاچه کردن میکروب‌ها:** فلوراید مستقیماً ترشح اسید توسط باکتری‌های مخرب دهان را فلج می‌کند تا نتوانند به دندان آسیب بزنند.',
