        body: 'اگر لثه‌های شما قبلاً کاملاً صورتی بوده و به مرور زمان تیره و کدر شده است، پای عوامل محیطی در میان است:\n\n۱. **سیگار، قلیان و دخانیات (ملانوز سیگاری‌ها):**\nدود داغ و نیکوتین موجود در توتون سلول‌های لثه را تحریک می‌کنند. سیستم دفاعی بدن برای محافظت از بافت لثه در برابر حرارت و سموم، شروع به تولید ملانین دفاعی می‌کند. در نتیجه، لثه‌های افراد سیگاری به خصوص در بخش جلوی فک بالا و پایین تیره و لکه‌دار می‌شود. خبر خوب این است که با ترک دخانیات، این لکه‌ها بعد از چند ماه تا چند سال کمرنگ‌تر می‌شوند.\n\n۲. **لکه‌های ناشی از پرکردگی نقره‌ای (خال آمالگام):**\nگاهی در کنار دندانی که با مواد سیاه و نقره‌ای (آمالگام) پر شده یا قبلاً کشیده شده است، یک لکه کوچک آبی تیره یا خاکستری می‌بینید. به این حالت «خال آمالگام» می‌گویند که ناشی از نفوذ ذره‌ای بسیار ریز از ذرات آمالگام به بافت نرم لثه است و هیچ خطری برای سلامتی ندارد.\n\n۳. **مصرف برخی داروها:**\nبعضی از داروهای خاص، مثل داروهای مالاریا، داروهای ضد افسردگی یا برخی آنتی‌بیوتیک‌های خاص (مثل مینوسیکلین) می‌توانند باعث تیرگی موقت بافت لثه شوند.'
