        title: 'نان سبوس‌دار و نشاسته‌ها؛ چسبندگی غذاهای پخته‌شده و تخریب خاموش مینا',
        body: 'وقتی صحبت از پوسیدگی دندان می‌شود، همه نگاه‌ها به سمت قند و شکلات می‌رود؛ اما کربوهیدرات‌های پیچیده و نشاسته‌ها چطور؟\n\nنشاسته خام به خودی خود پوسیدگی‌زایی کمی دارد؛ اما وقتی نشاسته پخته یا فرآوری می‌شود (مثل نان، بیسکویت، چیپس و کراکر)، آنزیم آمیلاز موجود در بزاق دهان زنجیره‌های بلند نشاسته را به قندهای ساده‌تر نظیر مالتوز و گلوکز می‌شکند. نکته پنهان در مورد **نان سبوس‌دار و نان‌های سفید صنعتی**، پدیده **«پاکسازی دهانی با تاخیر»** است:\n\n- تکه‌های نان یا کراکر هنگام جویدن خمیر شده و در شیارهای عمیق دندان‌های آسیاب و فواصل بین‌دندانی به شدت می‌چسبند.\n- اگرچه اسید تولیدشده از نشاسته به سرعت قند خالص نیست، اما ماندگاری طولانی‌مدت آن روی دندان (گاهی تا ۲ ساعت بعد از غذا) باعث می‌شود باکتری‌ها منبع غذایی مداومی داشته باشند.\n- البته نان‌های سبوس‌دار کامل به دلیل وجود فیبر و بافت سخت‌تر، نسبت به نان‌های سفید بدون سبوس بزاق بیشتری ترشح می‌کنند و از نظر سلامت عمومی و دستگاه گوارش انتخابی ایده‌آل هستند؛ اما از نظر دندانپزشکی، تمیز کردن فواصل دندان‌ها بعد از مصرف هر نوع نان با نخ دندان ضروری است.',
